@startuml

class Customer {
  + VATnumber : string
  + name : string
  + phoneNumber : string
  + address : string
}

class Package {
  + identifierCode : string
  + weight : float
  + deliveryType : string
}

class DeliveryCenter {
  + name : string
  + address : string
}

class Courier {
  + VATnumber : string
  + name : string
  + phoneNumber : string
}

Customer "1" -- "0..*" Package : sends
Customer "1" -- "1" DeliveryCenter : associated with
Customer "0..*" -- "1" Customer : recipient
Package "0..*" -- "1" Customer : recipient
Package "0..*" -- "1" DeliveryCenter : delivered to
Package "0..*" -- "0..1" Courier : assigned to
Courier "1" -- "1" DeliveryCenter : works in

@enduml

